# frozen_string_literal: true

require_relative "test_helper"

# Asserts that every invalid fixture fails with exactly the error code and
# messages the Python implementation produces (goldens under
# test/fixtures/golden/errors, regenerated by test/support/generate_goldens.rb).
# Error messages are part of the cross-implementation parity contract.
class ValidationErrorsTest < Minitest::Test
  cover "Lattice::Parser*"
  cover "Lattice::ConstraintEngine*"

  include FixtureHelpers

  ERRORS_DIR = File.join(FixtureHelpers::FIXTURES, "golden", "errors")
  INVALID_DIR = File.join(FixtureHelpers::FIXTURES, "invalid")

  # Mirrors the CLI's error classification (Lattice::CLI#load_and_check_model).
  def classify_failure(fixture)
    model = Lattice::Parser.load_model(fixture)
    engine = Lattice::ConstraintEngine.new(model)
    return ["validation_error", ["Model has no valid complete assignments."]] unless engine.can_complete?({})

    nil
  rescue Lattice::ValidationError => e
    ["validation_error", e.errors]
  rescue Lattice::ConstraintError => e
    ["constraint_error", [e.message]]
  end

  Dir[File.join(ERRORS_DIR, "*.json")].sort.each do |golden_path|
    name = File.basename(golden_path, ".json")

    define_method("test_error_parity_#{name}") do
      golden = JSON.parse(File.read(golden_path))
      failure = classify_failure(File.join(INVALID_DIR, "#{name}.json"))

      refute_nil failure, "expected #{name} to be invalid"
      assert_equal golden.fetch("code"), failure[0], "error code diverged for #{name}"
      assert_equal golden.fetch("errors"), failure[1], "error messages diverged for #{name}"
    end
  end
end
